import{_ as i,a0 as e,w as l,s as u,ao as p,I as a,x as t,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"弃 Ubuntu 转 Manjaro 一周后的使用体验 | LCTT x X-CMD","titleTemplate":false,"description":"弃 Ubuntu 转 Manjaro 一周后的使用体验 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"弃 Ubuntu 转 Manjaro 一周后的使用体验 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"弃 Ubuntu 转 Manjaro 一周后的使用体验 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week","title":"弃 Ubuntu 转 Manjaro 一周后的使用体验","tag":"202306","desc":""},"relativePath":"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week.md","filePath":"[post].md"}'),m={name:"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week.md"};function d(f,n,x,j,T,g){const r=e("Link");return l(),u("div",null,[n[43]||(n[43]=p('<h1 id="弃-ubuntu-转-manjaro-一周后的使用体验" tabindex="-1">弃 Ubuntu 转 Manjaro 一周后的使用体验 <a class="header-anchor" href="#弃-ubuntu-转-manjaro-一周后的使用体验" aria-label="Permalink to “弃 Ubuntu 转 Manjaro 一周后的使用体验”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/27/110506aou1bw5i6prwpm6m.jpg" alt=""></p><p>通常，我用的是基于 Ubuntu 的发行版进行工作，如 Pop!_OS、Zorin OS、Linux Mint 或 Ubuntu 本身。</p><p>它们不会干扰我的工作，同时又提供了顺滑的软件更新。更不用说，它们与我使用的英特尔-英伟达系统相容性良好。</p><p>所有的一切（可能是主观的）都能开箱即用。</p><p>然而，最近我决定在实体机上切换到 Arch Linux（我大部分时间都是在虚拟机上使用它）。</p><p>结果，我最终选择使用了 <strong>Manjaro Linux</strong>（一款基于 Arch 的发行版）。</p><h3 id="我选择-manjaro-linux-的原因" tabindex="-1">我选择 Manjaro Linux 的原因 <a class="header-anchor" href="#我选择-manjaro-linux-的原因" aria-label="Permalink to “我选择 Manjaro Linux 的原因”">​</a></h3><p>令我惊讶的是，即使是使用 <strong>Arch Linux 的立付 USB</strong>，我甚至无法解决 “nouveau DRM: core notifier timeout” 错误，更别提继续安装了。是的，我知道有向导式的 Arch Linux 安装程序，但是不论怎么样，连接的显示器都会闪烁并突出显示这个错误。</p><p>解决这个问题的最好办法是不使用我的最近刚刚升级的英伟达显卡。</p><p><em>很遗憾，我更喜欢英伟达的显卡……</em></p><p>AMD 的 RX 6600 XT 的价格与 RTX 3060 Ti 相当；对于 1440p 来说，购买那款显卡是没有意义的。</p><p>因此，在我这个情况下，RTX 3060 Ti 可能是问题所在。</p><p>虽然我找到了一些解决问题的方法，但是我太懒了。我只是想看看能否在不用付出太多努力的情况下体验一下 Arch Linux。</p><p><strong>所以，我做了以下的事情：</strong></p>',15)),a("p",null,[n[1]||(n[1]=t("下一个最佳选择就是尝试任何一个专门简化了麻烦的 ",-1)),s(r,{href:"https://itsfoss.com/arch-based-linux-distros/"},{default:o(()=>[...n[0]||(n[0]=[t("最佳的基于 Arch 的发行版",-1)])]),_:1}),n[2]||(n[2]=t("，对吧？",-1))]),n[44]||(n[44]=p('<p>这就是 <strong>Manjaro Linux</strong> 登场的地方。</p><p>Manjaro Linux 是一款流行的基于 Arch 的发行版，并且我注意到每次更新时都有各种改进（在虚拟机上使用时）。</p><p>此外，我喜欢 Manjaro 默认主题的强调色，很适合我的桌面体验。</p><p>所以，我决定试试看……</p><h3 id="manjaro-linux-起步有点困难" tabindex="-1">Manjaro Linux: 起步有点困难 <a class="header-anchor" href="#manjaro-linux-起步有点困难" aria-label="Permalink to “Manjaro Linux: 起步有点困难”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-linux-home.jpg" alt=""></p><p>使用专有的英伟达驱动程序安装 Manjaro 时我没有遇到任何问题。然而，最近的一个小版本更新，<strong>Manjaro Linux 21.2.6，</strong> 把我的系统弄乱了。</p>',7)),a("p",null,[n[4]||(n[4]=t("我无法访问登录界面和 ",-1)),s(r,{href:"https://itsfoss.com/what-is-tty-in-linux/"},{default:o(()=>[...n[3]||(n[3]=[t("TTY",-1)])]),_:1}),n[5]||(n[5]=t("（我只能看到主板制造商的标志）",-1))]),n[45]||(n[45]=p('<p>因此，我只能使用最新的 ISO 重新安装 Manjaro Linux，到目前为止一切都还好（千万别出问题）。</p><p>在我使用 Manjaro Linux 的过程中，我注意到了一些事情，有好有坏。</p><p>在这里，我分享一些我的经历。如果你还没有尝试过，这些经验应该对你帮助很大，可以让你更多地了解它。</p><h4 id="_1、简单的安装" tabindex="-1">1、简单的安装 <a class="header-anchor" href="#_1、简单的安装" aria-label="Permalink to “1、简单的安装”">​</a></h4><p>基于 Arch 的发行版的主要亮点是使安装过程变得简单。对我来说，完全没有遇到任何问题。</p><p>在我的第二块硬盘上安装 Manjaro Linux 是一件轻而易举的事情。引导加载程序正确配置，显示了 Manjaro 主题的启动菜单，让我可以选择 Windows/Manjaro Linux 进行双启动。</p><h4 id="_2、manjaro-欢迎页" tabindex="-1">2、Manjaro 欢迎页 <a class="header-anchor" href="#_2、manjaro-欢迎页" aria-label="Permalink to “2、Manjaro 欢迎页”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-welcome.jpg" alt=""></p><p>当尝试新东西时，欢迎体验在用户体验中占据了一大部分重要性。在这方面，Manjaro Linux 没有让人失望。</p><p>如果你仔细关注欢迎屏幕上提供的信息，你可以获得所有必要的信息。</p><p>GNOME 布局管理器能让你选择一个合适的布局，使你更加舒适。</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-desktop-layout.png" alt=""></p><p>然而，当我尝试在这里启用“<strong>窗口平铺</strong>”功能时，它却无法正常工作：</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-settings-welcome.png" alt=""></p><h4 id="_3、包管理器快速且功能丰富" tabindex="-1">3、包管理器快速且功能丰富 <a class="header-anchor" href="#_3、包管理器快速且功能丰富" aria-label="Permalink to “3、包管理器快速且功能丰富”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/pamac-manjaro.png" alt=""></p><p>考虑到 GNOME 是我最喜欢的桌面环境，我在软件中心（甚至是像 Pop!_Shop 这样特定于发行版的商店）上有过糟糕的经历。</p><p>虽然它们可以完成工作，但有时它们对我的期望反应不及预期。</p>',18)),a("p",null,[n[8]||(n[8]=t("在 Manjaro Linux 中，我发现安装了 ",-1)),s(r,{href:"https://wiki.manjaro.org/index.php/Pamac"},{default:o(()=>[...n[6]||(n[6]=[t("Pamac",-1)])]),_:1}),n[9]||(n[9]=t(" 作为包管理器。这似乎是 ",-1)),s(r,{href:"https://itsfoss.com/install-remove-software-manjaro/"},{default:o(()=>[...n[7]||(n[7]=[t("在 Manjaro Linux 上安装和卸载软件的最佳方式之一",-1)])]),_:1}),n[10]||(n[10]=t("。",-1))]),n[46]||(n[46]=p('<p>根据我的经验，它在安装和卸载软件时非常快速。在安装某些软件时，你还会收到关于软件包冲突或是否需要替换/删除某些软件包的提示。当你安装某些东西时，包管理器提供了关于可选/必需依赖项的大量信息。</p><p>总体来说，体验非常流畅，没有出现任何麻烦。为了提升体验，包管理器还可以通过调整 pamac 的偏好设置，快速启用对 <strong>Flatpaks/Snaps/AUR</strong> 的支持。</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-pamac-enable-flat-snap.png" alt=""></p><p>所以，你不必使用终端或不同的软件商店。一切都可在一个统一的平台下获得，这大大节省了时间。</p><h4 id="_4、尝试-zsh-shell" tabindex="-1">4、尝试 ZSH Shell <a class="header-anchor" href="#_4、尝试-zsh-shell" aria-label="Permalink to “4、尝试 ZSH Shell”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-terminal.png" alt=""></p><p>我习惯于在基于 Ubuntu 的发行版上使用 Bash shell。然而，Manjaro Linux 默认使用 Zsh shell。我相信 Zsh 比 Bash 更好，不过我很快会在另一篇文章中介绍并深入比较。</p><p>换句话说，我可以直接尝试不同的东西。令我兴奋的是，终端提示符和遵循 Manjaro 品牌的Shell（或终端）的主题也采用了 Manjaro 的强调色，非常令人印象深刻！</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-terminal-update.png" alt=""></p>',9)),a("p",null,[n[12]||(n[12]=t("因此，我没有必要在此处 ",-1)),s(r,{href:"https://itsfoss.com/customize-linux-terminal/"},{default:o(()=>[...n[11]||(n[11]=[t("自定义终端的外观",-1)])]),_:1}),n[13]||(n[13]=t("。",-1))]),a("p",null,[n[16]||(n[16]=t("要了解更多信息，你可以查看一些关于 ",-1)),s(r,{href:"https://linuxhandbook.com/why-zsh/"},{default:o(()=>[...n[14]||(n[14]=[t("Zsh 是什么",-1)])]),_:1}),n[17]||(n[17]=t(" 以及 ",-1)),s(r,{href:"https://linuxhandbook.com/install-zsh/"},{default:o(()=>[...n[15]||(n[15]=[t("如何安装它",-1)])]),_:1}),n[18]||(n[18]=t(" 的信息。",-1))]),n[47]||(n[47]=a("h4",{id:"_5、缺乏官方软件支持",tabindex:"-1"},[t("5、缺乏官方软件支持 "),a("a",{class:"header-anchor",href:"#_5、缺乏官方软件支持","aria-label":"Permalink to “5、缺乏官方软件支持”"},"​")],-1)),n[48]||(n[48]=a("p",null,[a("img",{src:"https://news.itsfoss.com/content/images/wordpress/2022/04/insync-manjaro.jpg",alt:""})],-1)),n[49]||(n[49]=a("p",null,"我希望这个情况能够很快改善。但目前来说，许多软件/工具只提供对 Ubuntu 和 Fedora 的官方支持。",-1)),n[50]||(n[50]=a("p",null,"你可以在各种工具中找到官方的 DEB/RPM 包，但它们都不能直接在 Manjaro Linux 上使用。",-1)),a("p",null,[n[20]||(n[20]=t("你得依赖 Arch Linux 仓库或 ",-1)),s(r,{href:"https://itsfoss.com/aur-arch-linux/"},{default:o(()=>[...n[19]||(n[19]=[t("AUR",-1)])]),_:1}),n[21]||(n[21]=t(" 中提供的软件包。",-1))]),a("p",null,[n[23]||(n[23]=t("幸运的是，很有可能在 AUR 或社区或发行版开发者维护的仓库中找到所需的软件。就像我能够在 Manjaro Linux 上运行 ",-1)),s(r,{href:"https://itsfoss.com/recommends/get-insync/"},{default:o(()=>[...n[22]||(n[22]=[t("Insync",-1)])]),_:1}),n[24]||(n[24]=t("，并使用文件管理器的集成扩展。",-1))]),n[51]||(n[51]=a("p",null,"然而，由于缺乏对该平台的官方支持，你可能会错过一些功能或快速更新。",-1)),a("p",null,[n[27]||(n[27]=t("当然，如果你依赖于 ",-1)),s(r,{href:"https://itsfoss.com/what-is-flatpak/"},{default:o(()=>[...n[25]||(n[25]=[t("Flatpak",-1)])]),_:1}),n[28]||(n[28]=t(" 或 Snap 软件包，这对你来说应该不是个问题。此外，如果你是 Linux 的新手，你可以参考我们的 ",-1)),s(r,{href:"https://itsfoss.com/flatpak-guide/"},{default:o(()=>[...n[26]||(n[26]=[t("Flatpak 指南",-1)])]),_:1}),n[29]||(n[29]=t(" 获取更多信息。",-1))]),n[52]||(n[52]=p('<h4 id="_6、缺少分数缩放" tabindex="-1">6、缺少分数缩放 <a class="header-anchor" href="#_6、缺少分数缩放" aria-label="Permalink to “6、缺少分数缩放”">​</a></h4><p>我有一个由 1080p 和 1440p 分辨率组成的双显示器。因此，分数缩放很有帮助，但我可以不用它来操作。</p><p>要在 Manjaro 上启用分数缩放，你需要安装支持 X11 缩放的 Mutter 和 GNOME 控制中心软件包。这些软件包包括：</p><ul><li><code>mutter-x11-scaling</code></li><li><code>gnome-control-center-x11-scaling</code></li></ul><p>这将替换你现有的 Mutter 和 GNOME 控制中心软件包。因此，你将失去桌面的默认主题/强调色设置。</p><p>你可能需要使用 GNOME “<ruby>调整<rt>Tweaks</rt></ruby>”应用来将一切调整正确。但是，这可能会令人感觉麻烦。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>总体而言，我喜欢在 Manjaro Linux 上的桌面体验。如果那个更新没有搞坏我的系统，我认为我会继续使用 Manjaro Linux 作为我的新日常操作系统。</p><p>你认为 Manjaro Linux 的优点和缺点是什么？我在我的新体验中有遗漏了什么吗？作为一个有经验的 Arch Linux 用户，你有任何建议吗？</p><p>请在下方评论中告诉我你的想法。</p><p><em>（题图：MJ/2726c4dd-5611-4ace-8c77-0db894ad6a23）</em></p><hr>',12)),a("p",null,[n[31]||(n[31]=t("via: ",-1)),s(r,{href:"https://news.itsfoss.com/manjaro-linux-experience/"},{default:o(()=>[...n[30]||(n[30]=[t("https://news.itsfoss.com/manjaro-linux-experience/",-1)])]),_:1})]),a("p",null,[n[35]||(n[35]=t("作者：",-1)),s(r,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...n[32]||(n[32]=[t("Ankush Das",-1)])]),_:1}),n[36]||(n[36]=t(" 选题：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...n[33]||(n[33]=[t("lujun9972",-1)])]),_:1}),n[37]||(n[37]=t(" 译者：ChatGPT 校对：",-1)),s(r,{href:"https://github.com/wxy"},{default:o(()=>[...n[34]||(n[34]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[40]||(n[40]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[38]||(n[38]=[t("LCTT",-1)])]),_:1}),n[41]||(n[41]=t(" 原创编译，",-1)),s(r,{href:"https://linux.cn/"},{default:o(()=>[...n[39]||(n[39]=[t("Linux中国",-1)])]),_:1}),n[42]||(n[42]=t(" 荣誉推出",-1))])])}const L=i(m,[["render",d]]);export{b as __pageData,L as default};
